70	KernelBinary::KernelBinary(std::shared_ptr<Function> func, std::vector<std::shared_ptr<Function>> pinnedGraph)
71	    : dynFunc(std::move(func)), pinnedGraph_(std::move(pinnedGraph))
72	{
73	    dynAttr = dynFunc->GetDyndevAttribute().get();
74	    devProg = (DevAscendProgram*)dynAttr->devProgBinary.data();
75	    kernelBin = RegisterKernelBinary(dynAttr->kernelBinary);
76	    workspaceSize = devProg->memBudget.Total();
77	    if (!IsLiteNPU(Platform::Instance().GetSoc().GetNPUArch())) { // litenpu does not need init device args
78	        InitCachedArgs();
79	        InitLaunchArgs();
80	        InitDeviceArgs();
81	        auto aicpuArgs = (AiCpuArgs*)aicpuArgBuf.data();
82	        DeviceLauncher::FillSwimLaneEnableInfo(toSubMachineConfig_);
83	        if (config::GetRuntimeOption<int64_t>(CFG_RUN_MODE) == CFG_RUN_MODE_SIM) {
84	            EslModelMemoryUtils eslMemoryUtils{true, true};
85	            DeviceLauncher::FillDeviceKernelArgs(eslMemoryUtils, dynAttr->devProgBinary, aicpuArgs->kArgs,
86	                                                 dynAttr->commGroupNames);
87	        } else {
88	            DeviceMemoryUtils deviceMemoryUtils;
89	            DeviceLauncher::FillDeviceKernelArgs(deviceMemoryUtils, dynAttr->devProgBinary, aicpuArgs->kArgs,
90	                                                 dynAttr->commGroupNames);
91	        }
92	    }
93	    kernelName_ = "PyPTO_" + dynFunc->GetOriginalRawName();
94	}
