96	KernelBinary::~KernelBinary()
97	{
98	    if (runtimeDynamicCellMatchOwned_ && runtimeDynamicCellMatchAddr_ != 0) {
99	        DevMemoryPool::Instance().FreeDevAddr(reinterpret_cast<uint8_t*>(runtimeDynamicCellMatchAddr_));
100	    }
101	    if (runtimeDynamicCellMatchHostOwned_ && runtimeDynamicCellMatchHostAddr_ != 0) {
102	        std::free(reinterpret_cast<void*>(runtimeDynamicCellMatchHostAddr_));
103	    }
104	    UnregisterKernelBinary(kernelBin);
105	    for (auto& cache : originShapeCaches) {
106	        DeviceLauncher::FreeControlFlowCache(cache.devCache);
107	    }
108	    for (auto& cache : inferShapeCaches) {
109	        DeviceLauncher::FreeControlFlowCache(cache.devCache);
110	    }
111	}
