115	uint8_t* KernelBinary::FindCtrlFlowCache(std::vector<std::vector<int64_t>>& inputs, bool isOriginShape)
116	{
117	    int64_t inHash = ControlFlowCache::Hash(inputs);
118	    auto& caches = isOriginShape ? originShapeCaches : inferShapeCaches;
119	    for (auto& cache : caches) {
120	        if (cache.hash == inHash) {
121	            return cache.devCache;
122	        }
123	    }
124	    return nullptr;
125	}
