139	uint8_t* KernelBinary::BuildControlFlowCache(std::vector<DeviceTensorData>& inputs, bool isOriginShape)
140	{
141	    DeviceLauncherConfig config;
142	    DeviceLauncher::DeviceLauncherConfigFillDeviceInfo(config);
143	    DevControlFlowCache* ctrlCache = nullptr;
144	    devProg->ctrlFlowCacheSize = DEFAULT_STITCH_CFGCACHE_SIZE;
145	    config.isCacheOriginShape = isOriginShape;
146	    EmulationMemoryUtils memUtils;
147	    size_t inputCount = dynAttr->startArgsInputTensorList.size();
148	    std::vector<DeviceTensorData> inputList(inputs.begin(), inputs.begin() + inputCount);
149	    std::vector<DeviceTensorData> outputList(inputs.begin() + inputCount, inputs.end());
150	    int ret = EmulationLauncher::BuildControlFlowCache(dynFunc.get(), memUtils, inputList, outputList, &ctrlCache,
151	                                                       config);
152	    if (ret != 0) {
153	        COMPILER_LOGE(CtrlErr::DEVICE_TASK_BUILD_FAILED, "control flow cache failed %d", ret);
154	        return nullptr;
155	    }
156	    // Emulation returns success + nullptr when DevProg.disableCtrlFlowCache is set.
157	    if (ctrlCache == nullptr) {
158	        return nullptr;
159	    }
160	
161	    uint8_t* devCache = DeviceLauncher::CopyControlFlowCache(ctrlCache);
162	    COMPILER_LOGD("control flow cache: %p", devCache);
163	    if (isOriginShape) {
164	        originShapeCaches.emplace_back(inputs, devCache);
165	    } else {
166	        inferShapeCaches.emplace_back(inputs, devCache);
167	    }
168	    return devCache;
169	}
