171	int64_t KernelBinary::GetWorkspaceSize(const std::vector<DeviceTensorData>& tensors)
172	{
173	    static const std::vector<DeviceTensorData> kEmptyOutputs;
174	    Evaluator eval{dynAttr->inputSymbolDict, &tensors, &kEmptyOutputs};
175	    dynamicCellMatchDescPatches_ = PrepareDynamicCellMatchDescPatches(*dynAttr, eval);
176	    PatchHostDynamicCellMatchTableDesc(devProg, dynamicCellMatchDescPatches_);
177	    if (dynAttr->maxDynamicAssembleOutcastMem.IsValid() || dynAttr->maxDynamicCellMatchTableMem.IsValid()) {
178	        if (dynAttr->maxDynamicAssembleOutcastMem.IsValid()) {
179	            devProg->memBudget.tensor.maxDynamicAssembleOutcastMem = eval.Evaluate(
180	                dynAttr->maxDynamicAssembleOutcastMem);
181	        }
182	        if (dynAttr->maxDynamicCellMatchTableMem.IsValid()) {
183	            devProg->memBudget.metadata.maxDynamicCellMatchTableMem = eval.Evaluate(
184	                dynAttr->maxDynamicCellMatchTableMem);
185	            uint64_t totalDynamicCellMatchSlotNum = devProg->memBudget.metadata.dynamicCellMatchSlotNum;
186	            devProg->memBudget.metadata.dynamicCellMatch = totalDynamicCellMatchSlotNum *
187	                                                           devProg->memBudget.metadata.maxDynamicCellMatchTableMem;
188	            ValidateDynamicCellMatchTableMemBudget(*dynAttr, devProg);
189	        }
190	        if (devProg->memBudget.metadata.dynamicCellMatch != lastPreparedDynamicCellMatchBytes_) {
191	            RefreshRuntimeDynamicCellMatchMeta(devProg->memBudget.metadata.dynamicCellMatch);
192	            lastPreparedDynamicCellMatchBytes_ = devProg->memBudget.metadata.dynamicCellMatch;
193	            devProg->devArgs.dynamicCellMatchAddr = runtimeDynamicCellMatchAddr_;
194	            devProg->devArgs.dynamicCellMatchCapacity = runtimeDynamicCellMatchCapacity_;
195	        }
196	        PatchHostDynamicCellMatchAddr(devProg);
197	        workspaceSize = devProg->memBudget.Total();
198	
199	        // check and pretty print total workspace consumption
200	        auto* wsChecker = RebuildableAttributeManager::GetInstance().GetAttr<RebuildableWorkspaceDesc>(dynFunc.get());
201	        MACHINE_LOGI_FULL("Memory Consumption: size=%ld\n%s\n", workspaceSize,
202	                          wsChecker
203	                              ->PrettyDumpSize(devProg->memBudget.tensor.maxDynamicAssembleOutcastMem,
204	                                               devProg->memBudget.debug.Total())
205	                              .c_str());
206	        MACHINE_ASSERT(uint64_t(workspaceSize) ==
207	                       wsChecker->GetSizeForCheckOnly(devProg->memBudget.tensor.maxDynamicAssembleOutcastMem,
208	                                                      devProg->memBudget.debug.Total()));
209	        mem_dump::DumpMemoryOverview(*devProg, dynFunc.get(), static_cast<uint64_t>(workspaceSize));
210	    }
211	    return workspaceSize;
212	}
