214	std::pair<AiCpuArgs*, int64_t> KernelBinary::BuildKernelArgs(const std::vector<DeviceTensorData>& tensors)
215	{
216	    auto& disableL2List = dynAttr->disableL2List;
217	    auto aicpuArgs = (AiCpuArgs*)aicpuArgBuf.data();
218	    int64_t* inputp = (int64_t*)(aicpuArgs + 1);
219	    auto tensorData = (DevTensorData*)(inputp + 2);
220	    const int64_t totalTensorCount = inputp[0] + inputp[1];
221	    MACHINE_ASSERT((int64_t)tensors.size() == totalTensorCount) << "mismatch tensor size";
222	    for (size_t i = 0; i < (size_t)totalTensorCount; ++i) {
223	        auto& t = tensors[i];
224	        auto addr = (uint64_t)t.GetAddr();
225	        if (unlikely(addr && disableL2List.size() && disableL2List[i])) {
226	            COMPILER_LOGI("mismatch tensor addr");
227	            addr += l2Offset;
228	        }
229	        tensorData->address = addr;
230	        tensorData->dataType = tensors[i].GetDataType();
231	        auto& shape = t.GetShape();
232	        tensorData->shape.dimSize = shape.size();
233	        for (int j = 0; j < tensorData->shape.dimSize; ++j) {
234	            tensorData->shape.dim[j] = shape[j];
235	        }
236	        tensorData++;
237	    }
238	
239	    WriteDynamicCellMatchStridePatchesToLaunchArgs(inputp, dynamicCellMatchDescPatches_);
240	
241	    return {aicpuArgs, aicpuArgBuf.size() * sizeof(int64_t)};
242	}
