244	bool KernelBinary::CheckArgs(const std::vector<DeviceTensorData>& tensors) const
245	{
246	    if (tensors.size() != argTypes.size()) {
247	        return false;
248	    }
249	    for (size_t i = 0; i < tensors.size(); ++i) {
250	        auto& t = tensors[i];
251	        auto& type = argTypes[i];
252	        if (unlikely(t.GetDataType() != type.GetDataType())) {
253	            return false;
254	        }
255	        if (unlikely(t.Format() != type.Format())) {
256	            return false;
257	        }
258	        auto& shape1 = type.GetShape();
259	        auto& shape2 = t.GetShape();
260	        if (unlikely(shape1.size() != shape2.size())) {
261	            return false;
262	        }
263	        for (size_t j = 0; j < shape1.size(); ++j) {
264	            if (unlikely((shape1[j] != -1) && (shape1[j] != shape2[j]))) {
265	                return false;
266	            }
267	        }
268	    }
269	    return true;
270	}
