297	void KernelBinary::ResetRuntimeDynamicCellMatchPool(bool useHostMirror) const
298	{
299	    if (runtimeDynamicCellMatchCapacity_ == 0) {
300	        return;
301	    }
302	    if (useHostMirror) {
303	        if (runtimeDynamicCellMatchHostAddr_ == 0) {
304	            return;
305	        }
306	        // Host mirror: fill each uint64 with AICORE_TASK_INIT (not byte 0xFF).
307	        ResetRuntimeDynamicCellMatchPoolHost(runtimeDynamicCellMatchHostAddr_, runtimeDynamicCellMatchCapacity_, false);
308	        return;
309	    }
310	    if (runtimeDynamicCellMatchAddr_ == 0) {
311	        return;
312	    }
313	    ResetRuntimeDynamicCellMatchPoolHost(runtimeDynamicCellMatchAddr_, runtimeDynamicCellMatchCapacity_, true);
314	}
