329	void KernelBinary::InitCachedArgs()
330	{
331	    auto argNum = dynAttr->startArgsInputLogicalTensorList.size() + dynAttr->startArgsOutputLogicalTensorList.size();
332	    const uint64_t maxPatchCount = dynAttr->dynamicCellMatchLaunchMetaList.size();
333	    auto argSize = sizeof(AiCpuArgs) + 2 * sizeof(int64_t) + argNum * sizeof(DevTensorData) + sizeof(uint64_t) +
334	                   maxPatchCount * sizeof(DevDynamicCellMatchStridePatch);
335	    MACHINE_ASSERT(argSize % 0x8 == 0);
336	    aicpuArgBuf.resize(argSize / 0x8);
337	
338	    auto aicpuArgs = new (aicpuArgBuf.data()) AiCpuArgs();
339	    aicpuArgs->kArgs.inputs = nullptr;
340	    aicpuArgs->kArgs.outputs = nullptr;
341	
342	    int64_t* inputp = (int64_t*)(aicpuArgs + 1);
343	    inputp[0] = dynAttr->startArgsInputLogicalTensorList.size();
344	    inputp[1] = dynAttr->startArgsOutputLogicalTensorList.size();
345	    const uint64_t tensorCount = static_cast<uint64_t>(inputp[0]) + static_cast<uint64_t>(inputp[1]);
346	    *reinterpret_cast<uint64_t*>(reinterpret_cast<DevTensorData*>(inputp + 2) + tensorCount) = 0;
347	
348	    l2Offset = GetRuntimeL2Offset();
349	
350	    for (auto& t : dynAttr->startArgsInputLogicalTensorList) {
351	        if (t == nullptr) {
352	            continue;
353	        }
354	        argTypes.emplace_back(t->Datatype(), nullptr, t->GetShape(), t->Format());
355	    }
356	    for (auto& t : dynAttr->startArgsOutputLogicalTensorList) {
357	        if (t == nullptr) {
358	            continue;
359	        }
360	        argTypes.emplace_back(t->Datatype(), nullptr, t->GetShape(), t->Format());
361	    }
362	}
