381	void KernelBinary::RefreshRuntimeDynamicCellMatchMeta(uint64_t needBytes)
382	{
383	    if (needBytes == 0) {
384	        if (runtimeDynamicCellMatchOwned_ && runtimeDynamicCellMatchAddr_ != 0) {
385	            DevMemoryPool::Instance().FreeDevAddr(reinterpret_cast<uint8_t*>(runtimeDynamicCellMatchAddr_));
386	        }
387	        if (runtimeDynamicCellMatchHostOwned_ && runtimeDynamicCellMatchHostAddr_ != 0) {
388	            std::free(reinterpret_cast<void*>(runtimeDynamicCellMatchHostAddr_));
389	        }
390	        runtimeDynamicCellMatchAddr_ = 0;
391	        runtimeDynamicCellMatchHostAddr_ = 0;
392	        runtimeDynamicCellMatchCapacity_ = 0;
393	        runtimeDynamicCellMatchOwned_ = false;
394	        runtimeDynamicCellMatchHostOwned_ = false;
395	        return;
396	    }
397	    if (runtimeDynamicCellMatchAddr_ != 0 && runtimeDynamicCellMatchHostAddr_ != 0 &&
398	        runtimeDynamicCellMatchCapacity_ >= needBytes) {
399	        return;
400	    }
401	    uint64_t oldAddr = runtimeDynamicCellMatchAddr_;
402	    uint64_t oldHostAddr = runtimeDynamicCellMatchHostAddr_;
403	    bool oldOwned = runtimeDynamicCellMatchOwned_;
404	    bool oldHostOwned = runtimeDynamicCellMatchHostOwned_;
405	    DeviceMemoryUtils deviceMemoryUtils;
406	    auto* newPtr = deviceMemoryUtils.AllocDev(needBytes, nullptr);
407	    if (newPtr == nullptr) {
408	        ASSERT(false) << "alloc dynamic cell match meta failed, needBytes=" << needBytes;
409	        return;
410	    }
411	    auto* newHostPtr = static_cast<uint8_t*>(std::malloc(static_cast<size_t>(needBytes)));
412	    if (newHostPtr == nullptr) {
413	        DevMemoryPool::Instance().FreeDevAddr(newPtr);
414	        ASSERT(false) << "alloc host dynamic cell match meta failed, needBytes=" << needBytes;
415	        return;
416	    }
417	    runtimeDynamicCellMatchAddr_ = reinterpret_cast<uint64_t>(newPtr);
418	    runtimeDynamicCellMatchHostAddr_ = reinterpret_cast<uint64_t>(newHostPtr);
419	    runtimeDynamicCellMatchCapacity_ = needBytes;
420	    runtimeDynamicCellMatchOwned_ = true;
421	    runtimeDynamicCellMatchHostOwned_ = true;
422	    ResetRuntimeDynamicCellMatchPool(true);
423	    ResetRuntimeDynamicCellMatchPool(false);
424	    if (oldOwned && oldAddr != 0) {
425	        DevMemoryPool::Instance().FreeDevAddr(reinterpret_cast<uint8_t*>(oldAddr));
426	    }
427	    if (oldHostOwned && oldHostAddr != 0) {
428	        std::free(reinterpret_cast<void*>(oldHostAddr));
429	    }
430	}
431	
432	void KernelBinary::SetAiCpuSoOverride(std::vector<uint8_t> soBytes) { g_aicpuSoOverride = std::move(soBytes); }
433	
434	void KernelBinary::InitAiCpuSoBin(DeviceArgs& devArgs)
435	{
436	    std::vector<uint8_t> buffer;
437	    std::string source;
438	    if (!g_aicpuSoOverride.empty()) {
439	        buffer = g_aicpuSoOverride; // bundle-supplied .so takes precedence over the on-disk copy
440	        source = "kernel-bundle AICPU_SO";
441	    } else {
442	        std::string fileName = GetPyptoLibPath() + "/libtilefwk_backend_server.so";
443	        source = fileName;
444	        buffer = ReadFile(fileName);
445	    }
446	    if (buffer.empty()) {
447	        MACHINE_LOGE(DevCommonErr::FILE_ERROR,
448	                     "Read bin form tilefwk_backend_server.so failed, please check the so[%s]", source.c_str());
449	        return;
450	    }
451	    void* devBufferPtr = CopyDataToDevice(buffer.data(), buffer.size());
452	    if (devBufferPtr == nullptr) {
453	        MACHINE_LOGE(DevCommonErr::MEMCPY_FAILED, "Failed to copy buffer of [%s] to device.", source.c_str());
454	        return;
455	    }
456	    devArgs.aicpuSoBin = reinterpret_cast<uint64_t>(devBufferPtr);
457	    devArgs.aicpuSoLen = buffer.size();
458	    MACHINE_LOGI("[aicpu-so] init backend server .so from %s, len=%zu", source.c_str(), buffer.size());
459	    HOST_PERF_TRACE(TracePhase::RunDevKernelInitAicpuSo);
460	}
