462	void KernelBinary::GetAicoreRegs(const ArchInfo archInfo, std::vector<int64_t>& regs, std::vector<int64_t>& regsPmu)
463	{
464	    if (archInfo == ArchInfo::DAV_3510) {
465	        RuntimeAgent::GetAicoreRegInfoForDAV3510(regs, regsPmu);
466	        return;
467	    }
468	    if (archInfo == ArchInfo::DAV_2201) {
469	        std::vector<int64_t> aiv;
470	        std::vector<int64_t> aic;
471	        if (RuntimeAgent::GetAgent().GetAicoreRegInfo(aic, aiv, ADDR_MAP_TYPE_REG_AIC_CTRL) != 0) {
472	            return;
473	        }
474	        regs.insert(regs.end(), aic.begin(), aic.end());
475	        regs.insert(regs.end(), aiv.begin(), aiv.end());
476	
477	        std::vector<int64_t> aivPmu;
478	        std::vector<int64_t> aicPmu;
479	        if (RuntimeAgent::GetAgent().GetAicoreRegInfo(aicPmu, aivPmu, ADDR_MAP_TYPE_REG_AIC_PMU_CTRL) != 0) {
480	            return;
481	        }
482	        regsPmu.insert(regsPmu.end(), aicPmu.begin(), aicPmu.end());
483	        regsPmu.insert(regsPmu.end(), aivPmu.begin(), aivPmu.end());
484	    }
485	}
486	
487	int KernelBinary::InitDeviceArgsCore(DeviceArgs& args)
488	{
489	    std::vector<int64_t> regs;
490	    std::vector<int64_t> regsPmu;
491	    GetAicoreRegs(args.archInfo, regs, regsPmu);
492	
493	    args.nrAic = regs.size() / SUB_CORE;
494	    args.nrAiv = args.nrAic * AIV_PER_AICORE;
495	    uint64_t nrCore = regs.size() + AICPU_NUM_OF_RUN_AICPU_TASKS;
496	    args.sharedBuffer = reinterpret_cast<uint64_t>(DevAlloc(nrCore * SHARED_BUFFER_SIZE));
497	    args.corePmuAddr = reinterpret_cast<uint64_t>(DevAlloc(nrCore * PMU_BUFFER_SIZE));
498	    if (args.sharedBuffer == 0 || args.corePmuAddr == 0) {
499	        MACHINE_LOGE(DevCommonErr::ALLOC_FAILED, "Fail alloc sharedBuffer[%lu] or corePmuAddr[%lu].", args.sharedBuffer,
500	                     args.corePmuAddr);
501	        return static_cast<int>(DevCommonErr::ALLOC_FAILED);
502	    }
503	
504	    // core reg
505	    size_t regSize = regs.size() * sizeof(uint64_t);
506	    args.coreRegAddr = reinterpret_cast<uint64_t>(CopyDataToDevice(regs.data(), regSize));
507	    if (args.coreRegAddr == 0) {
508	        MACHINE_LOGE(DevCommonErr::MEMCPY_FAILED, "Fail to copy aicore reg data from host to device.");
509	        return static_cast<int>(DevCommonErr::MEMCPY_FAILED);
510	    }
511	
512	    // core reg pmu
513	    args.corePmuRegAddr = reinterpret_cast<uint64_t>(CopyDataToDevice(regsPmu.data(), regSize));
514	    if (args.corePmuRegAddr == 0) {
515	        MACHINE_LOGE(DevCommonErr::MEMCPY_FAILED, "Fail to copy aicore pmu reg data from host to device.");
516	        return static_cast<int>(DevCommonErr::MEMCPY_FAILED);
517	    }
518	    MACHINE_LOGI("Dev args :aic %u aiv %u, sharedBuffer %lx coreRegAddr %lx corePmuRegAddr %lx", args.nrAic, args.nrAiv,
519	                 args.sharedBuffer, args.coreRegAddr, args.corePmuRegAddr);
520	
521	    args.taskWastTime = reinterpret_cast<uint64_t>(DevAlloc(sizeof(uint64_t)));
522	    size_t shmSize = sizeof(dynamic::RuntimeDataRingBufferHead) + dynamic::DEVICE_SHM_SIZE +
523	                     dynamic::DEVICE_TASK_QUEUE_SIZE * args.nrAicpu;
524	    args.runtimeDataRingBufferAddr = reinterpret_cast<uint64_t>(DevAlloc(shmSize));
525	
526	    // pmu evt info
527	    std::vector<int64_t> pmuEvtType;
528	    PmuCommon::InitPmuEventType(args.archInfo, pmuEvtType);
529	    args.pmuEventAddr = reinterpret_cast<uint64_t>(
530	        CopyDataToDevice(pmuEvtType.data(), pmuEvtType.size() * sizeof(int64_t)));
531	    if (args.pmuEventAddr == 0) {
532	        MACHINE_LOGE(DevCommonErr::MEMCPY_FAILED, "Fail to copy pmu evt type from host to device.");
533	        return static_cast<int>(DevCommonErr::MEMCPY_FAILED);
534	    }
535	
536	    if (!DeviceDfx::GetInstance().Init(args)) {
537	        MACHINE_LOGE(DevCommonErr::INIT_FAILED, "Device dfx info init not success.");
538	        return static_cast<int>(DevCommonErr::INIT_FAILED);
539	    }
540	    return 0;
541	}
542	
543	int KernelBinary::InitDeviceArgs(DeviceArgs& args)
544	{
545	    memset_s(&args, sizeof(args), 0, sizeof(args));
546	    args.deviceId = GetLogDeviceId();
547	    args.archInfo = static_cast<ArchInfo>(Platform::Instance().GetSoc().GetNPUArch());
548	    uint32_t aicpuNum = args.archInfo == ArchInfo::DAV_3510 ? dynamic::DEVICE_MAX_AICPU_NUM : 5;
549	    uint32_t maxAicpuNum = static_cast<uint32_t>(Platform::Instance().GetSoc().GetAICPUNum());
550	    args.nrValidAic = GetCfgBlockdim();
551	    args.nrAicpu = std::min(aicpuNum, maxAicpuNum);
552	    args.scheCpuNum = dynamic::CalcSchAicpuNumByBlockDim(args.nrValidAic, args.nrAicpu, args.archInfo);
553	    MACHINE_LOGD("DevArgs: block dim[%u], aicpu num[%u], max aicpu num[%u], sche cpu num[%u].", args.nrValidAic,
554	                 args.nrAicpu, maxAicpuNum, args.scheCpuNum);
555	
556	    InitAiCpuSoBin(args);
557	
558	    return InitDeviceArgsCore(args);
559	}
