561	void KernelBinary::InitDeviceArgs()
562	{
563	    std::call_once(g_initOnce, []() {
564	        HostProf::GetInstance().RegHostProf();
565	        InitializeErrorCallback();
566	        ASSERT(DevCommonErr::INIT_FAILED, InitDeviceArgs(g_deviceArgs) == 0);
567	        int64_t* devArgsAddr = static_cast<int64_t*>(CopyDataToDevice(&g_deviceArgs, sizeof(DeviceArgs)));
568	        if (devArgsAddr == nullptr) {
569	            MACHINE_LOGE(DevCommonErr::MEMCPY_FAILED, "Failed to copy args to device.");
570	            ASSERT(false);
571	        }
572	        if (config::GetRuntimeOption<int64_t>(CFG_RUN_MODE) != CFG_RUN_MODE_SIM) {
573	            if (LoadAicpuOp::GetInstance().GetBuiltInOpBinHandle(devArgsAddr) != 0) {
574	                MACHINE_LOGE(DevCommonErr::GET_HANDLE_FAILED, "Get builtInOp Funchandle failed\n");
575	                ASSERT(false);
576	            }
577	            DevicePerf::GetInstance().InitAndStartDumpThread(g_deviceArgs);
578	            AdumpRegExceptionDump();
579	        }
580	    });
581	}
