58	extern "C" int32_t Execute(MachineTask* task, FunctionCache& cache)
59	{
60	    if (config::GetHostOption<int64_t>(COMPILE_STAGE) >= CS_TENSOR_GRAPH &&
61	        config::GetHostOption<int64_t>(COMPILE_STAGE) <= CS_EXECUTE_GRAPH) {
62	        MACHINE_LOGI("Compile stage terminates after execution graph generation.");
63	        return 0;
64	    }
65	    if (task == nullptr || task->GetFunction() == nullptr) {
66	        MACHINE_LOGE(DevCommonErr::NULLPTR, "Machine task or function of machine task is null.");
67	        return 0;
68	    }
69	    Function* function = task->GetFunction();
70	    if (function->IsFunctionType(DYNAMIC_FUNC_TYPE_SET) && function->GetGraphType() == GraphType::TILE_GRAPH) {
71	        MACHINE_LOGI("The codegen of the current function is executed last");
72	        // When expression fusion, don't need tile graph codegen.
73	        return 0;
74	    }
75	    (void)GenCode(task, cache);
76	    /* finish compile add function cache */
77	    cache.Insert(function->GetFunctionHash(), *function);
78	    return 0;
79	}
