81	static void HandleExecuteGraph(FunctionCache& cache, Linker& linker, Function* func);
82	void FindAllExpression(FunctionCache& cache, Linker& linker, Function* func)
83	{
84	    if (func->IsDynloop()) {
85	        auto dynloopAttr = func->GetDynloopAttribute();
86	        auto ss = SymbolicScalar(dynloopAttr->iterSymbolName);
87	        linker.AddSymbol(ss);
88	    }
89	    if (func->IsFunctionTypeAndGraphType(
90	            {FunctionType::DYNAMIC, FunctionType::DYNAMIC_LOOP, FunctionType::DYNAMIC_LOOP_PATH},
91	            GraphType::TENSOR_GRAPH)) {
92	        MACHINE_LOGI("Compile control: %s", func->Dump().c_str());
93	        for (auto& callee : GetCalleeList(cache, func)) {
94	            FindAllExpression(cache, linker, callee);
95	        }
96	        if (func->IsFunctionTypeAndGraphType(FunctionType::DYNAMIC_LOOP, GraphType::TENSOR_GRAPH)) {
97	            auto attr = func->GetDynloopAttribute();
98	            linker.AddPrimaryExpressionForLoopBes(func, attr->Begin());
99	            linker.AddPrimaryExpressionForLoopBes(func, attr->End());
100	            linker.AddPrimaryExpressionForLoopBes(func, attr->Step());
101	
102	            for (const DynloopFunctionPath& path : attr->GetPathList()) {
103	                Function* loopPath = path.GetRoot();
104	                for (auto& cond : path.GetPathCondList()) {
105	                    linker.AddPrimaryExpressionForLoopPathCond(loopPath, cond.GetCond());
106	                }
107	            }
108	        }
109	    } else if (func->GetGraphType() == GraphType::TILE_GRAPH) {
110	        MACHINE_LOGI("Compile tile: %s", func->Dump().c_str());
111	        Function* root = func->GetRootFunction();
112	        FindAllExpression(cache, linker, root);
113	    } else if (func->GetGraphType() == GraphType::EXECUTE_GRAPH) {
114	        HandleExecuteGraph(cache, linker, func);
115	    } else if (func->GetGraphType() == GraphType::BLOCK_GRAPH) {
116	        for (auto& op : func->Operations()) {
117	            if (op.GetOpcode() == Opcode::OP_VEC_DUP) {
118	                if (op.HasAttr(OpAttributeKey::dynScalar)) {
119	                    auto dynScalar = op.GetSymbolicScalarAttribute(OpAttributeKey::dynScalar);
120	                    linker.AddPrimaryExpressionForDevLeafOp(func, &op, dynScalar);
121	                }
122	            }
123	        }
124	    } else {
125	        ASSERT(DevCommonErr::PARAM_INVALID, false)
126	            << "Impossible function type: " << GetFunctionTypeNameDict().Find(func->GetFunctionType());
127	    }
128	}
