130	static void HandleExecuteGraph(FunctionCache& cache, Linker& linker, Function* func)
131	{
132	    MACHINE_LOGI("Compile root: %s", func->Dump().c_str());
133	    MainBlockCondBulider builder;
134	    builder.CollectCallopMainBlockConds(func);
135	    for (auto& callopAttr : func->GetCallopAttrList()) {
136	        for (auto& arg : callopAttr->GetLinearArgList()) {
137	            linker.AddPrimaryExpressionForDevRootCoa(func, arg);
138	        }
139	        auto hash = callopAttr->GetCalleeHash();
140	        Function* leafFunc = cache.GetCacheFunction(hash);
141	        if (leafFunc == nullptr) {
142	            continue;
143	        }
144	        builder.CollectLeafMainBlockConds(leafFunc, callopAttr->GetLinearArgList());
145	        FindAllExpression(cache, linker, leafFunc);
146	    }
147	    for (auto& incast : func->inCasts_) {
148	        for (auto& arg : incast->GetRawTensor()->GetDynRawShape()) {
149	            linker.AddPrimaryExpressionForDevRootCoa(func, arg);
150	        }
151	    }
152	    for (auto& outcast : func->outCasts_) {
153	        for (auto& arg : outcast->GetRawTensor()->GetDynRawShape()) {
154	            linker.AddPrimaryExpressionForDevRootCoa(func, arg);
155	        }
156	    }
157	    SymbolicScalar cond = builder.BuildMainBlockExpression();
158	    linker.SetMainBlockExpressionForDevRootCoa(func, cond);
159	}
