168	static void ReplaceSlotIndex(DyndevFunctionAttribute* attr, std::set<int>& slotUsed,
169	                             std::unordered_map<int, int>& slotIdxMapping)
170	{
171	    IncastOutcastLink& inoutLink = attr->inoutLink;
172	
173	    for (auto idx : slotUsed) {
174	        if (!slotIdxMapping.count(idx)) {
175	            slotIdxMapping.emplace(idx, slotIdxMapping.size());
176	        }
177	    }
178	
179	    auto replaceSlotIdx = [&slotIdxMapping](std::vector<int>& slots) {
180	        for (int& slot : slots) {
181	            slot = slotIdxMapping.count(slot) ? slotIdxMapping[slot] : -1;
182	        }
183	        slots.erase(std::remove(slots.begin(), slots.end(), -1), slots.end());
184	    };
185	
186	    inoutLink.totalSlot = slotIdxMapping.size();
187	    for (Function* devRoot : attr->funcGroup.devRootList) {
188	        Function* devTile = attr->rootTileDict[devRoot];
189	
190	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, inoutLink.ioslotDict.count(devTile))
191	            << "Function pointer " << devTile->GetMagicName() << " not found in ioslotDict";
192	        IncastOutcastSlot& ioslot = inoutLink.ioslotDict[devTile];
193	
194	        for (auto& incastSlots : ioslot.incastSlot) {
195	            replaceSlotIdx(incastSlots);
196	        }
197	
198	        for (auto& outcastSlots : ioslot.outcastSlot) {
199	            replaceSlotIdx(outcastSlots);
200	        }
201	    }
202	
203	    replaceSlotIdx(inoutLink.inputSlotIndexList);
204	    replaceSlotIdx(inoutLink.outputSlotIndexList);
205	    replaceSlotIdx(inoutLink.assembleSlotIndexList);
206	    replaceSlotIdx(inoutLink.shmemTensorSlotIndexList);
207	    replaceSlotIdx(inoutLink.partialUpdateSlotIdexList);
208	    for (auto& slot : inoutLink.inplaceSlotIndexList) {
209	        if (slot != -1)
210	            slot = slotIdxMapping[slot];
211	    }
212	
213	    auto replaceSlotIdxForFunc = [replaceSlotIdx](Function* func) {
214	        std::shared_ptr<TensorSlotScope> scope = func->GetSlotScope();
215	        if (scope) {
216	            replaceSlotIdx(scope->constructAssembleSlotList);
217	        }
218	    };
219	    for (auto loopPathFunc : attr->funcGroup.loopPathList) {
220	        replaceSlotIdxForFunc(loopPathFunc);
221	    }
222	
223	    inoutLink.UpdateRuntimeSlotKindSetList();
224	}
