243	static void SimplifySlots(DyndevFunctionAttribute* attr, std::unordered_map<int, int>& slotIdxMapping)
244	{
245	    IncastOutcastLink& inoutLink = attr->inoutLink;
246	    std::set<int> slotUsed;
247	
248	    MarkUsedSlotsFromInoutLink(inoutLink, slotUsed);
249	    for (Function* devRoot : attr->funcGroup.devRootList) {
250	        Function* devTile = attr->rootTileDict[devRoot];
251	
252	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, inoutLink.ioslotDict.count(devTile))
253	            << "Function pointer " << devTile->GetMagicName() << " not found in ioslotDict";
254	        IncastOutcastSlot& ioslot = inoutLink.ioslotDict[devTile];
255	
256	        for (auto& incastSlots : ioslot.incastSlot) {
257	            if (incastSlots.empty()) {
258	                MACHINE_LOGW("devTile: %s", devTile->GetMagicName().c_str());
259	                continue;
260	            }
261	            int32_t simplifiedIncastSlot = -1;
262	            for (auto& incastSlot : incastSlots) {
263	                if (slotUsed.count(incastSlot)) {
264	                    simplifiedIncastSlot = incastSlot;
265	                    break;
266	                }
267	            }
268	            if (simplifiedIncastSlot != -1) {
269	                incastSlots.front() = simplifiedIncastSlot;
270	            }
271	            incastSlots.resize(1); // meaningless to maintain multi incast slots
272	            slotUsed.insert(incastSlots.front());
273	        }
274	    }
275	
276	    for (Function* devRoot : attr->funcGroup.devRootList) {
277	        Function* devTile = attr->rootTileDict[devRoot];
278	
279	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, inoutLink.ioslotDict.count(devTile))
280	            << "Function pointer " << devTile->GetMagicName() << " not found in ioslotDict";
281	        IncastOutcastSlot& ioslot = inoutLink.ioslotDict[devTile];
282	        for (auto& outcastSlots : ioslot.outcastSlot) {
283	            ASSERT(DevCommonErr::PARAM_CHECK_FAILED, !outcastSlots.empty()) << "devTile: " << devTile->GetMagicName();
284	            bool outcastSlotFound = false;
285	            for (auto& outcastSlot : outcastSlots) {
286	                outcastSlotFound = outcastSlotFound || slotUsed.count(outcastSlot);
287	            }
288	            if (!outcastSlotFound) {
289	                slotUsed.insert(outcastSlots.front());
290	            }
291	        }
292	    }
293	
294	    ReplaceSlotIndex(attr, slotUsed, slotIdxMapping);
295	}
