355	static void CollectConstructAssembleRuntimeSlotsFromFunction(FunctionCache& cache, Function* func,
356	                                                             DyndevFunctionAttribute* attr,
357	                                                             std::unordered_map<int, int>& slotIdxMapping)
358	{
359	    if (func->IsFunctionTypeAndGraphType(FunctionType::DYNAMIC_LOOP_PATH, GraphType::TENSOR_GRAPH)) {
360	        auto scope = func->GetSlotScope();
361	        if (scope != nullptr) {
