372	static void BuildConstructAssembleNeedAllocRuntimeSlots(FunctionCache& cache, Function* func,
373	                                                        DyndevFunctionAttribute* attr,
374	                                                        std::unordered_map<int, int>& slotIdxMapping)
375	{
376	    attr->constructAssembleNeedAllocRuntimeSlots.clear();
377	    CollectConstructAssembleRuntimeSlotsFromFunction(cache, func, attr, slotIdxMapping);
378	
379	    const std::unordered_set<int> assembleSlotIndexSet(attr->inoutLink.assembleSlotIndexList.begin(),
380	                                                       attr->inoutLink.assembleSlotIndexList.end());
381	    for (Function* devRoot : attr->funcGroup.devRootList) {
382	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, attr->rootTileDict.count(devRoot))
383	            << "Function not found in rootTileDict";
384	        Function* tile = attr->rootTileDict[devRoot];
385	        if (!attr->inoutLink.ioslotDict.count(tile)) {
386	            continue;
387	        }
388	        const IncastOutcastSlot& ioslot = attr->inoutLink.ioslotDict.at(tile);
389	        ForEachNeedAllocAssembleOutcastSlot(tile, ioslot, assembleSlotIndexSet, [&](int slot) {
390	            AddConstructAssembleNeedAllocRuntimeSlot(attr, slot, slotIdxMapping);
391	        });
392	    }
393	}
