402	    const auto& primaryExprs = exprTable->GetPrimaryExpressionSet();
403	    for (const auto& expr : primaryExprs) {
404	        if (expr == nullptr) {
405	            continue;
406	        }
407	        if (exprTable->CheckExprDependCore(expr, valDependTensorMeta.tensorNameToDependCore,
408	                                           valDependTensorMeta.valDependMap)) {
409	            needSync = true;
410	            break;
411	        }
412	    }
413	    if (needSync) {
414	        controlFlowOss << std::setw(indent * TABSIZE) << ' ' << "WaitAicoreStart(startArgs);\n";
415	    }
