446	static void FillL2PrefetchInfo(std::shared_ptr<DyndevFunctionAttribute> attr)
447	{
448	    uint64_t idx = 0;
449	    for (auto& param : attr->startArgsInputTensorList) {
450	        const auto& tensor = param.get();
451	        auto asc_tensor = tensor.GetStorage();
452	        if (asc_tensor == nullptr) {
453	            idx++;
454	            attr->disableL2List.emplace_back(0);
455	            continue;
456	        }
457	        if (tensor.GetStorage()->GetCachePolicy(CachePolicy::PREFETCH)) {
458	            attr->l2InfoList.emplace_back(L2Info(tensor.GetStorage()->MemorySize(), idx));
459	        }
460	        if (tensor.GetStorage()->GetCachePolicy(CachePolicy::NONE_CACHEABLE)) {
461	            attr->disableL2List.emplace_back(1);
462	        } else {
463	            attr->disableL2List.emplace_back(0);
464	        }
465	        idx++;
466	    }
467	    for (auto& param : attr->startArgsOutputTensorList) {
468	        const auto& tensor = param.get();
469	        auto asc_tensor = tensor.GetStorage();
470	        if (asc_tensor == nullptr) {
471	            idx++;
472	            attr->disableL2List.emplace_back(0);
473	            continue;
474	        }
475	        if (tensor.GetStorage()->GetCachePolicy(CachePolicy::NONE_CACHEABLE)) {
476	            attr->disableL2List.emplace_back(1);
477	        } else {
478	            attr->disableL2List.emplace_back(0);
479	        }
480	        idx++;
481	    }
482	    MACHINE_LOGI("Need prefetch tensor size is:%zu\n", attr->l2InfoList.size());
483	    return;
484	}
