505	    dynamic::EncodeDevAscendProgram(function, size, nullptr);
506	    dynAttrPtr->devProgBinary.resize(size);
507	
508	    dynamic::DevAscendProgram* devProg = reinterpret_cast<dynamic::DevAscendProgram*>(&dynAttrPtr->devProgBinary[0]);
509	    dynamic::EncodeDevAscendProgram(function, size, devProg);
510	    devProg->disableCtrlFlowCache = disableCtrlFlowCache ? 1 : 0;
511	
512	    if (config::GetPassDefaultConfig(npu::tile_fwk::KEY_PRINT_PROGRAM, false)) {
513	        devProg->DumpFile(config::LogTopFolder() + "/program.tifwkbintxt");
514	        std::string loopDirPath = config::LogTopFolder() + "/loop";
515	        CreateDir(loopDirPath, true);
516	        for (size_t index = 0; index < dynAttrPtr->funcGroup.loopList.size(); index++) {
517	            Function* func = dynAttrPtr->funcGroup.loopList[index];
518	            func->DumpFile(loopDirPath + "/" + func->GetMagicName() + ".tifwkgr");
519	        }
520	    }
521	    devProg->RelocProgram(reinterpret_cast<int64_t>(devProg), 0);
522	    if (config::GetPassDefaultConfig(npu::tile_fwk::KEY_PRINT_PROGRAM, false)) {
523	        SaveFile(config::LogTopFolder() + "/program.tifwkbin", dynAttrPtr->devProgBinary);
524	    }
525	    MACHINE_LOGI("Dev prog binary size is:%zu\n", dynAttrPtr->devProgBinary.size());
526	}
