528	std::vector<SymbolicExpressionTable*> GetAllExpressionTable(
529	    DyndevFunctionAttribute::ExpressionTableDictGroup& exprTableGroup)
530	{
531	    std::vector<SymbolicExpressionTable*> exprTableList;
532	    for (auto& [func, exprTable] : exprTableGroup.loopBesDict) {
533	        (void)func;
534	        exprTableList.push_back(&exprTable);
535	    }
536	    for (auto& [func, ifDict] : exprTableGroup.loopPathCondDict) {
537	        (void)func;
538	        for (auto& [expr, exprTable] : ifDict) {
539	            (void)expr;
540	            exprTableList.push_back(&exprTable);
541	        }
542	    }
543	    for (auto& [func, exprTable] : exprTableGroup.devRootCoaDict) {
544	        (void)func;
545	        exprTableList.push_back(&exprTable);
546	    }
547	    for (auto& [func, opDict] : exprTableGroup.devLeafOpDict) {
548	        (void)func;
549	        for (auto& [op, exprTable] : opDict) {
550	            (void)op;
551	            exprTableList.push_back(&exprTable);
552	        }
553	    }
554	    return exprTableList;
555	}
