557	static void ConstructCodeInfo(struct EncodeDevAscendFunctionParam& encodeDevAscendFunctionParam,
558	                              std::map<uint64_t, Function*>& leafDict, std::shared_ptr<DyndevFunctionAttribute> attr)
559	{
560	    attr->cceCodeInfo.resize(leafDict.size() + 2);
561	    /* cceIdx 0 for dummy callop */
562	    attr->cceCodeInfo[0].coreType = static_cast<uint32_t>(CoreType::HUB);
563	    attr->cceCodeInfo[0].psgId = 0;
564	    attr->cceCodeInfo[0].funcHash = 0;
565	    encodeDevAscendFunctionParam.calleeHashIndexDict[0] = 0;
566	
567	    /* cceIdx 1 for HUB_MIX dummy callop */
568	    attr->cceCodeInfo[1].coreType = static_cast<uint32_t>(CoreType::HUB_MIX);
569	    attr->cceCodeInfo[1].psgId = 0;
570	    attr->cceCodeInfo[1].funcHash = HUB_MIX_DUMMY_HASH;
571	    encodeDevAscendFunctionParam.calleeHashIndexDict[HUB_MIX_DUMMY_HASH] = 1;
572	
573	    int leafIndex = 2;
574	    for (auto& [hash, leaf] : leafDict) {
575	        auto leafFuncAttr = leaf->GetLeafFuncAttribute();
576	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, leafFuncAttr != nullptr) << "leafFuncAttr is null\n";
577	        encodeDevAscendFunctionParam.calleeHashIndexDict[hash] = leafIndex;
578	        attr->devLeafIndex2Hash[leafIndex] = hash;
579	        MACHINE_LOGI("Dyndev.codegen: [ %d ] hash= %lu binpath= %s", leafIndex, hash, leafFuncAttr->binPath.c_str());
580	        attr->cceCodeInfo[leafIndex].coreType = static_cast<uint32_t>(leafFuncAttr->coreType);
581	        if (leaf->IsDummyFunction())
582	            attr->cceCodeInfo[leafIndex].coreType = static_cast<uint32_t>(CoreType::HUB);
583	        attr->cceCodeInfo[leafIndex].psgId = leaf->GetProgramId();
584	        attr->cceCodeInfo[leafIndex].funcHash = hash;
585	        attr->cceCodeInfo[leafIndex].aicpuLeafCode = leafFuncAttr->aicpuLeafCode;
586	        attr->cceCodeInfo[leafIndex].wrapVecId = static_cast<int32_t>(leafFuncAttr->aivCore);
587	        attr->cceCodeInfo[leafIndex].mixResourceType = static_cast<uint32_t>(leafFuncAttr->mixResourceType);
588	        leafIndex++;
589	    }
590	
591	    encodeDevAscendFunctionParam.cceCodeInfoList = attr->cceCodeInfo;
592	    return;
593	}
