595	static void EncodeOutcastProperty(EncodeDevAscendFunctionParam& encodeDevAscendFunctionParam,
596	                                  const IncastOutcastLink* inoutLink, const IncastOutcastSlot* slot)
597	{
598	    encodeDevAscendFunctionParam.outcastDescList.clear();
599	    encodeDevAscendFunctionParam.assembleSlotList.clear();
600	    Function* devRoot = encodeDevAscendFunctionParam.devRoot;
601	
602	    std::unordered_map<std::shared_ptr<RawTensor>, int> incastDict;
603	    for (size_t incastIndex = 0; incastIndex < devRoot->GetIncast().size(); incastIndex++) {
604	        incastDict[devRoot->GetIncast()[incastIndex]->GetRawTensor()] = incastIndex;
605	    }
606	
607	    std::vector<RuntimeSlotKindSet> outcastSlotKindSetList(slot->outcastSlot.size());
608	    for (size_t outcastIndex = 0; outcastIndex < slot->outcastSlot.size(); outcastIndex++) {
609	        for (auto& slotIndex : slot->outcastSlot[outcastIndex]) {
610	            outcastSlotKindSetList[outcastIndex] = outcastSlotKindSetList[outcastIndex] |
611	                                                   inoutLink->runtimeSlotKindSetList[slotIndex];
612	        }
613	    }
614	    encodeDevAscendFunctionParam.outcastDescList.resize(slot->outcastSlot.size());
615	    for (size_t outcastIndex = 0; outcastIndex < slot->outcastSlot.size(); outcastIndex++) {
616	        RuntimeSlotDesc& desc = encodeDevAscendFunctionParam.outcastDescList[outcastIndex];
617	        if (outcastSlotKindSetList[outcastIndex].Contains(RuntimeSlotKind::INPUT)) {
618	            desc.kind = RuntimeSlotKind::INPUT;
619	        } else if (outcastSlotKindSetList[outcastIndex].Contains(RuntimeSlotKind::OUTPUT)) {
620	            desc.kind = RuntimeSlotKind::OUTPUT;
621	        } else if (outcastSlotKindSetList[outcastIndex].Contains(RuntimeSlotKind::ASSEMBLE_OUTCAST)) {
622	            desc.kind = RuntimeSlotKind::ASSEMBLE_OUTCAST;
623	        } else {
624	            int incastIndex = -1;
625	            auto outcastRawTensor = devRoot->GetOutcast()[outcastIndex]->GetRawTensor();
626	            if (devRoot->outIncastLinkMap.count(outcastRawTensor)) {
627	                auto incastRawTensor = devRoot->outIncastLinkMap[outcastRawTensor];
628	                incastIndex = incastDict[incastRawTensor];
629	            }
630	            if (incastIndex != -1) {
631	                desc.kind = RuntimeSlotKind::INPLACE_INCAST;
632	                desc.inplaceIncastIndex = incastIndex;
633	            } else {
634	                desc.kind = RuntimeSlotKind::EXCLUSIVE_OUTCAST;
635	            }
636	        }
637	    }
638	
639	    for (size_t outcastIndex = 0; outcastIndex < slot->outcastSlot.size(); outcastIndex++) {
640	        if (encodeDevAscendFunctionParam.outcastDescList[outcastIndex].kind == RuntimeSlotKind::ASSEMBLE_OUTCAST) {
641	            for (auto& slotIndex : slot->outcastSlot[outcastIndex]) {
642	                encodeDevAscendFunctionParam.assembleSlotList.push_back(slotIndex);
643	            }
644	        }
645	    }
646	}
