666	                 "the loop function operation: %s size is %u hitting the maxinum single-loop-operation limit:%u.\n",
667	                 funcMagicName.c_str(), CallOpSize, CallOpmaxSize);
668	    ASSERT(DevCommonErr::PARAM_CHECK_FAILED, CallOpSize <= CallOpmaxSize)
669	        << " loopFunction: " << funcMagicName << " CallOpSize: " << CallOpSize << " CallOpmaxSize: " << CallOpmaxSize;
