736	static void NormalizeExpressionTables(Linker& linker, std::ostringstream& expressionOss)
737	{
738	    expressionOss << "#ifndef TILE_FWK_EXPRESSION_H"
739	                  << "\n"
740	                  << "#define TILE_FWK_EXPRESSION_H"
741	                  << "\n";
742	    auto& exprTableGroup = linker.GetExpressionTableDictGroup();
743	    std::vector<SymbolicExpressionTable*> exprTableList = GetAllExpressionTable(exprTableGroup);
744	    linker.GetSymbolTable()->NormalizeForSymbol();
745	    for (auto exprTable : exprTableList) {
746	        exprTable->NormalizeForSymbolTable(*linker.GetSymbolTable());
747	        expressionOss << exprTable->BuildExpressionList();
748	    }
749	}
