786	static void RunBuildControlFlowStage(IrBackendContext& irBackendCtx, FunctionCache& cache, Linker& linker,
787	                                     Function* function, const std::shared_ptr<DyndevFunctionAttribute>& attr,
788	                                     const std::string& expName, std::vector<std::string>& exprSrcFiles,
789	                                     ValDependTensorMeta& valDependTensorMeta, std::string& controlFlowSource,
790	                                     std::string& expressionSource)
791	{
792	    // Host-machine compile sub-step index for monitor progress (1-based when enabled, -1 when disabled).
793	    const int hmStep = MonitorManager::Instance().AllocHostMachineStepIndex();
794	    MonitorStageScope buildControlFlowScope(STAGE_HOST_MACHINE, hmStep, STAGE_DYNDEV_BUILD_CONTROL_FLOW, 0);
795	    bool useNewIr = function->body_ != nullptr;
796	    CollectExpressions(irBackendCtx, cache, linker, function, useNewIr);
797	    PrepareDyndevAttrForControlFlow(function, attr);
798	
799	    std::ostringstream controlFlowOss;
800	    std::ostringstream expressionOss;
801	    NormalizeExpressionTables(linker, expressionOss);
802	
803	    std::unordered_map<int, int> slotIdxMapping;
804	    if (useNewIr) {
805	        std::ostringstream exprHeaderOss;
806	        attr->rootTileDict.clear();
807	        CollectRootTileDict(cache, function, attr->rootTileDict);
808	        BuildConstructAssembleNeedAllocRuntimeSlots(cache, function, attr.get(), slotIdxMapping);
809	        auto& exprTableGroup = linker.GetExpressionTableDictGroup();
810	        std::vector<SymbolicExpressionTable*> exprTableList = GetAllExpressionTable(exprTableGroup);
811	        GetInputCse getInputCse = ExprBatchGenerator::CollectGetInputCse(exprTableList);
812	        irBackendCtx.getInputCse = &getInputCse;
813	        BuildControlFlowFromIR(irBackendCtx, cache, linker, ".pypto", function, slotIdxMapping, attr->funcGroup,
814	                               attr->rootTileDict, controlFlowOss, expressionOss, exprHeaderOss, 0, expName,
815	                               exprSrcFiles, valDependTensorMeta);
816	    } else {
817	        EmitControlFlowSources(cache, linker, function, attr, expName, exprSrcFiles, valDependTensorMeta,
818	                               controlFlowOss, expressionOss, slotIdxMapping);
819	    }
820	    expressionOss << "#endif/*TILE_FWK_EXPRESSION_H*/"
821	                  << "\n";
822	
823	    controlFlowSource = controlFlowOss.str();
824	    expressionSource = expressionOss.str();
825	    FinalizeControlFlowSlotMapping(attr, slotIdxMapping);
826	}
