828	static void RunCompileControlFlowStage(Function* function, const std::shared_ptr<DyndevFunctionAttribute>& attr,
829	                                       const std::string& aicpuDirPath, const std::string& controlFlowSource,
830	                                       const std::string& expressionSource, std::vector<std::string>& exprSrcFiles)
831	{
832	#ifdef __x86_64__
833	    std::string cflags = "-mno-sse2 -mno-sse";
834	#else
835	    std::string cflags = "-mgeneral-regs-only";
836	#endif
837	
838	    const std::string funcHash = function->GetFunctionHash().Data();
839	    const std::string arm64TargetToolPath = Arm64TargetTool("g++");
840	    const bool hasArm64DevCompile = IsPathExist(arm64TargetToolPath);
841	    const std::string controlFlowHostFilePath = aicpuDirPath + "/controlFlow_host_" + funcHash + ".cpp";
842	
843	    const int hmStep = MonitorManager::Instance().AllocHostMachineStepIndex();
844	    const int srcCount = static_cast<int>(exprSrcFiles.size() + 1) * (hasArm64DevCompile ? 2 : 1);
845	    const std::string hmLabel = std::string(STAGE_DYNDEV_CONTROL_FLOW_COMPILE) + funcHash;
846	    MonitorStageScope aicpuHostCompileScope(STAGE_HOST_MACHINE, hmStep, hmLabel, srcCount);
847	
848	    attr->hostControlFlowBinary = CompileAndLoadSection(controlFlowSource, controlFlowHostFilePath, aicpuDirPath,
849	                                                        exprSrcFiles, "g++", "ld", "objcopy", ".pypto",
850	                                                        IsNeedDumpAicpuKernel(controlFlowHostFilePath), cflags);
851	    AlignUpTo(attr->hostControlFlowBinary, 0x8, 0);
852	    std::string funcName = function->GetMagicName() + function->GetFunctionHash().Data();
853	    CompileControlFlow(aicpuDirPath, funcName, controlFlowSource, expressionSource);
854	    if (hasArm64DevCompile) {
855	        static const std::string BISHENG_LD_CMD = "ld.lld";
856	        std::string controlFlowDevFilePath = aicpuDirPath + "/controlFlow_dev_" + funcHash + ".cpp";
857	        MACHINE_LOGI("Compile control flow src file[%s] with arm64 target tool[%s].", controlFlowDevFilePath.c_str(),
858	                     arm64TargetToolPath.c_str());
859	        attr->devControlFlowBinary = CompileAndLoadSection(
860	            controlFlowSource, controlFlowDevFilePath, aicpuDirPath, exprSrcFiles, arm64TargetToolPath, BISHENG_LD_CMD,
861	            Arm64TargetTool("objcopy"), ".pypto", IsNeedDumpAicpuKernel(controlFlowDevFilePath));
862	    } else {
863	        // brk #0
864	        MACHINE_LOGW("Arm64 target tool is not found.");
865	        attr->devControlFlowBinary = std::vector<uint8_t>{0xd4, 0x20, 0x00, 0x00};
866	    }
867	    AlignUpTo(attr->devControlFlowBinary, 0x8, 0);
868	}
