892	static void RunEncodeStage(Function* function, const std::shared_ptr<DyndevFunctionAttribute>& attr, Linker& linker,
893	                           EncodeDevAscendFunctionParam& encodeDevAscendFunctionParam, bool disableCtrlFlowCache)
894	{
895	    const int hmStep = MonitorManager::Instance().AllocHostMachineStepIndex();
896	    MonitorStageScope encodeScope(STAGE_HOST_MACHINE, hmStep, STAGE_DYNDEV_ENCODE,
897	                                  static_cast<int>(attr->funcGroup.devRootList.size()));
898	    attr->devEncodeList.resize(attr->funcGroup.devRootList.size());
899	    topo_dump::StaticTopoCsvWriter staticTopo;
900	    for (auto& devRoot : attr->funcGroup.devRootList) {
901	        int devRootKey = attr->funcGroup.devRootList.GetIndex(devRoot);
902	        MACHINE_LOGI("Dyndev.encode: %s", devRoot->GetRawName().c_str());
903	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, attr->rootTileDict.count(devRoot))
904	            << "devRoot not found in rootTileDict";
905	        Function* devTile = attr->rootTileDict[devRoot];
906	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, attr->inoutLink.ioslotDict.count(devTile))
907	            << "devTile not found in rootTileDict";
908	        IncastOutcastSlot* slot = &attr->inoutLink.ioslotDict[devTile];
909	        encodeDevAscendFunctionParam.symbolTable = linker.GetSymbolTable();
910	        if (linker.GetExpressionTableDictGroup().devRootCoaDict.count(devRoot) != 0) {
911	            encodeDevAscendFunctionParam
912	                .expressionTable = &linker.GetExpressionTableDictGroup().devRootCoaDict.find(devRoot)->second;
913	        }
914	        encodeDevAscendFunctionParam.devRoot = devRoot;
915	        encodeDevAscendFunctionParam.slot = slot;
916	        EncodeOutcastProperty(encodeDevAscendFunctionParam, &attr->inoutLink, slot);
917	        uint64_t size = 0;
918	        EncodeDevAscendFunction(function, encodeDevAscendFunctionParam, size, nullptr);
919	        attr->devEncodeList[devRootKey].resize(size);
920	        DevAscendFunction* funcBin = reinterpret_cast<DevAscendFunction*>(&attr->devEncodeList[devRootKey][0]);
921	        funcBin->rootHash = devRoot->GetFunctionHash().GetHash();
922	        funcBin->funcKey = devRootKey;
923	        funcBin->stackWorkSpaceSize = devTile->GetStackWorkespaceSize();
924	        funcBin->getInputDataCount = 0;
925	        funcBin->getTensorDataCount = 0;
926	        EncodeDevAscendFunction(function, encodeDevAscendFunctionParam, size, funcBin);
927	        auto maxCVCoreUsage = devRoot->GetMaxCVCoreUsage();
928	        funcBin->SetMaxCV(maxCVCoreUsage.first, maxCVCoreUsage.second);
929	        staticTopo.WriteFunction(devRootKey, *funcBin);
930	        funcBin->Reloc(-reinterpret_cast<int64_t>(funcBin), true);
931	        uint32_t CallOpmaxSize = MAX_STITCH_LEAFFUNC_NUM;
932	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, CallOpmaxSize <= STITCH_FUNCTION_MAX_SIZE)
933	            << " CallOpmaxSize : " << CallOpmaxSize << "exceeds the maximum allowed value of 65535.";
934	        if (funcBin->GetOperationSize() > CallOpmaxSize) {
935	            OverCallOpMaxNum(devRoot, funcBin);
936	        }
937	    }
938	    SetDyndevProgBinary(function, disableCtrlFlowCache);
939	}
