941	static void RunCodeGenStage(const std::shared_ptr<DyndevFunctionAttribute>& attr,
942	                            std::map<uint64_t, Function*>& leafDict)
943	{
944	    std::mutex leafDictMutex;
945	
946	    MonitorManager::Instance().SetRootFuncCount(GetRootFuncNum(attr));
947	
948	    std::deque<std::function<void(void)>> tasks;
949	    for (auto& devRoot : attr->funcGroup.devRootList) {
950	        std::function<void(void)> task = [&devRoot, &attr, &leafDict, &leafDictMutex]() {
951	            Function* devTile = attr->rootTileDict[devRoot];
952	            bool isDynamicAligned = devTile->paramConfigs_.dynamicAlignedOps;
953	            npu::tile_fwk::CodeGenCtx codeGenCtx("", config::GetEmitPath("kernel_aicore"), false, isDynamicAligned);
954	            npu::tile_fwk::CodeGen codeGen(codeGenCtx);
955	            COMPILER_LOGI("Function :[%s] starts executing codegen and binary compilation",
956	                          devTile->GetMagicName().c_str());
957	            codeGen.GenCode(*devTile);
958	            MainBlockCondBulider::Gencode(devTile);
959	
960	            std::lock_guard<std::mutex> lock(leafDictMutex);
961	            for (auto& [psgId, leaf] : devRoot->programs_) {
962	                (void)psgId;
963	                auto hash = leaf->GetFunctionHash().GetHash();
964	                if (!leafDict.count(hash)) {
965	                    leafDict[hash] = leaf;
966	                    MACHINE_LOGI("Dyndev.codegen: %s", leaf->GetRawName().c_str());
967	                } else {
968	                    MACHINE_LOGE(HostBackEndErr::DUPLICATE_LEAF_FUNC_HASH, " Duplicate func hash %lu name %s", hash,
969	                                 leaf->GetRawName().c_str());
970	                }
971	            }
972	        };
973	        tasks.push_back(task);
974	    }
975	
976	    MonitorManager::Instance().PrintCurrentTotalElapsed("Stage CodeGen cce code generation completed");
977	    unsigned threadNum = GetCGThreadNum();
978	    ParallelExecuteAndWait(threadNum, tasks);
979	}
980	
981	static void CompileDyndevFunction(Function* function, FunctionCache& cache, [[maybe_unused]] const std::string& ccePath)
982	{
983	    ASSERT(HostBackEndErr::RUN_PASS_FAILED,
984	           (PassManager::Instance().RunPass(Program::GetInstance(), *function, "ExecuteGraph") == SUCCESS));
985	    if (Platform::Instance().GetSoc().GetNPUArch() == NPUArch::DAV_3510 && config::IsRuntimeDebugAllEnabled()) {
986	        mix_info::DumpMixInfo(function);
987	    }
988	    std::shared_ptr<DyndevFunctionAttribute> attr = function->GetDyndevAttribute();
989	    ASSERT(DevCommonErr::PARAM_CHECK_FAILED, attr != nullptr) << "DyndevFunctionAttribute is nullptr\n";
990	    Linker linker(attr->symbolTable, attr->funcGroup, attr->exprTableDictGroup);
991	    bool hasAicoreKernelLink = false;
992	#ifdef BUILD_WITH_CANN
993	    hasAicoreKernelLink = config::GetHostOption<int64_t>(COMPILE_STAGE) != CS_CODEGEN_INSTRUCTION &&
994	                          std::getenv("ASCEND_HOME_PATH") != nullptr;
995	#endif
996	    // Each *StepCount is the number of HostMachine sub-stages (always 1 here), not op/workload.
997	    // Must match Run*Stage order and AllocHostMachineStepIndex() call count (3 without AICore link, 4 with).
998	    constexpr int buildControlFlowStepCount = 1;   // DynDev:BuildControlFlow
999	    constexpr int controlFlowCompileStepCount = 1; // DynDev:ControlFlowCompile
1000	    constexpr int aicoreKernelStepCount = 1;       // DynDev:AICoreKernelCompile (when hasAicoreKernelLink)
1001	    constexpr int encodeStepCount = 1;             // DynDev:Encode (MonitorStageScope opSize = devRoot count)
1002	    MonitorManager::Instance().BeginHostMachineCompileGroup(buildControlFlowStepCount + controlFlowCompileStepCount +
1003	                                                            (hasAicoreKernelLink ? aicoreKernelStepCount : 0) +
1004	                                                            encodeStepCount);
1005	    uint64_t tilingKey = OpInfoManager::GetInstance().GetOpTilingKey();
1006	    std::string aicpuDirPath = config::GetEmitPath("kernel_aicpu");
1007	    npu::tile_fwk::CreateDir(aicpuDirPath, true);
1008	    const std::string expName = "expression_" + std::to_string(tilingKey) + ".h";
1009	    std::vector<std::string> exprSrcFiles;
1010	    ValDependTensorMeta valDependTensorMeta;
1011	    std::string controlFlowSource;
1012	    std::string expressionSource;
1013	    IrBackendContext irBackendCtx;
1014	
1015	    RunBuildControlFlowStage(irBackendCtx, cache, linker, function, attr, expName, exprSrcFiles, valDependTensorMeta,
1016	                             controlFlowSource, expressionSource);
1017	
1018	    std::string expressionFilePath = aicpuDirPath + "/" + expName;
1019	    if (IsNeedDumpAicpuKernel(expressionFilePath)) {
1020	        SaveFile(expressionFilePath, expressionSource);
1021	    }
1022	
1023	    RunCompileControlFlowStage(function, attr, aicpuDirPath, controlFlowSource, expressionSource, exprSrcFiles);
1024	
1025	    std::map<uint64_t, Function*> leafDict;
1026	    RunCodeGenStage(attr, leafDict);
1027	
1028	    struct EncodeDevAscendFunctionParam encodeDevAscendFunctionParam = {};
1029	    ConstructCodeInfo(encodeDevAscendFunctionParam, leafDict, attr);
1030	    encodeDevAscendFunctionParam.inoutLink = &attr->inoutLink;
1031	
1032	    std::string kernelPath;
1033	#ifdef BUILD_WITH_CANN
1034	    if (hasAicoreKernelLink) {
1035	        if (!RunCompileAicoreKernelStage(function, leafDict, encodeDevAscendFunctionParam, ccePath, kernelPath)) {
1036	            return;
1037	        }
1038	    }
1039	#endif
1040	
1041	    attr->kernelBinary = ReadFile(kernelPath);
1042	    MACHINE_LOGD("KernelBinary size[%zu].", attr->kernelBinary.size());
1043	
1044	    RunEncodeStage(function, attr, linker, encodeDevAscendFunctionParam, valDependTensorMeta.disableCtrlFlowCache);
1045	}
1046	
1047	MachineTask* GenCode(MachineTask* task, FunctionCache& cache)
1048	{
1049	    npu::tile_fwk::CodeGenCtx codeGenCtx("", config::GetEmitPath("kernel_aicore"));
1050	    npu::tile_fwk::CreateDir(codeGenCtx.cceDir, true);
1051	    npu::tile_fwk::CodeGen codeGen(codeGenCtx);
1052	    auto function = task->GetFunction();
1053	    /* each leafFunction inside is compiled to a standalone object file.
1054	     * the filepath of the object file is updated to the binPath_ member.
1055	     */
1056	    if (function->GetGraphType() == GraphType::TILE_GRAPH) {
1057	        MonitorManager::Instance().SetRootFuncCount(1);
1058	        MonitorStageScope codeGenScope("CodeGen");
1059	        MonitorManager::Instance().SwitchStageReset();
1060	        MonitorManager::Instance().PrintCurrentTotalElapsed("Stage CodeGen start for TILE_GRAPH");
1061	        COMPILER_LOGI("Start (TILE_GRAPH) CodeGen stage...");
1062	        codeGen.GenCode(*function);
1063	        MainBlockCondBulider::Gencode(function);
1064	    } else {
1065	        if (function->IsFunctionType(FunctionType::DYNAMIC)) {
1066	            MonitorStageScope codeGenScope("CodeGen");
1067	            MonitorManager::Instance().SwitchStageReset();
1068	            MonitorManager::Instance().PrintCurrentTotalElapsed("Stage CodeGen start for DYNAMIC");
1069	            COMPILER_LOGI("Start (DYNAMIC) CodeGen stage...");
1070	            std::string cce_path = RealPath(codeGenCtx.cceDir) + "/";
1071	            CompileDyndevFunction(function, cache, cce_path);
1072	        } else {
1073	            COMPILER_LOGI("The current function does not need to do codegen");
1074	        }
1075	    }
1076	
1077	    return task;
1078	}
1079	} // namespace npu::tile_fwk
