/*!
 * \file ir_backend.cpp
 * \brief New SCF IR based control flow building functions.
 */

#include "machine/host/ir_backend.h"

#include "ir/kind_traits.h"
#include "tilefwk/pypto_fwk_log.h"
#include "tilefwk/error_code.h"
#include "tilefwk/platform.h"
