114	int DeviceLauncher::DeviceLaunchOnceWithDeviceTensorData(
115	    Function* function, const std::vector<DeviceTensorData>& inputList, const std::vector<DeviceTensorData>& outputList,
116	    RtStream aicoreStream, bool streamSynchronize, [[maybe_unused]] CachedOperator* cachedOperator,
117	    [[maybe_unused]] DevControlFlowCache* inputDevCtrlCache, const DeviceLauncherConfig& config)
118	{
119	    MACHINE_LOGI("Kernel Launch");
120	    aicoreStream = aicoreStream == nullptr ? GetContextAiCoreStream() : aicoreStream;
121	    KernelLaunchInfo launchInfo(GetContextScheStream(), GetContextCtrlStream(), aicoreStream, config.blockdim,
122	                                config.aicpuNum);
123	    // 1.Add stream to capture model
124	    int rc = SetCaptureStream(launchInfo.aicoreStream, launchInfo.schedStream, launchInfo.isCaptureActivate);
125	    if (rc < 0) {
126	        return rc;
127	    }
128	
129	    // 2. Change capture mode to relaxed
130	    if (launchInfo.isCaptureActivate) {
131	        ExchangeCaptureModeRelax();
132	    }
133	    HOST_PERF_TRACE(TracePhase::RunDeviceSetCapture);
134	
135	    HostProf::GetInstance().SetProfFunction(function);
136	    rc = AclInit(nullptr);
137	    if (rc != 0 && rc != ACLRT_ERROR_REPEAT_INITIALIZE) {
138	        return rc;
139	    }
140	    HOST_PERF_TRACE(TracePhase::RunDeviceInit);
141	
142	    CheckAscendDriverVersionOnboard();
143	    CheckDeviceId();
144	
145	    auto kernel = std::make_unique<KernelBinary>(Program::GetInstance().GetFunctionSharedPtr(function));
146	
147	    std::vector<DeviceTensorData> tensors;
148	    tensors.reserve(inputList.size() + outputList.size());
149	    tensors.insert(tensors.end(), inputList.begin(), inputList.end());
150	    tensors.insert(tensors.end(), outputList.begin(), outputList.end());
151	
152	    int64_t wsSize = kernel->GetWorkspaceSize(tensors);
153	    HOST_PERF_TRACE(TracePhase::RunDevInitInOutTensor);
154	
155	    int64_t* wsAddr = nullptr;
156	    if (wsSize > 0) {
157	        DeviceMemoryUtils devMem;
158	        wsAddr = reinterpret_cast<int64_t*>(devMem.AllocDev(static_cast<size_t>(wsSize), nullptr));
159	        if (wsAddr == nullptr) {
160	            MACHINE_LOGE(RtErr::RT_MALLOC_FAILED, "Failed to alloc workspace of size %ld", wsSize);
161	            return -1;
162	        }
163	    }
164	
165	    uint8_t* ctrlFlowCache = PrepareLaunch(kernel.get(), tensors, nullptr, LaunchMode::DEVICE_RT);
166	
167	    DataDumpInit();
168	    rc = LaunchKernel(aicoreStream, ctrlFlowCache, kernel.get(), wsAddr, tensors, false, 0);
169	    if (rc < 0) {
170	        return rc;
171	    }
172	
173	    rc = RunWithProfile(aicoreStream, launchInfo.schedStream, launchInfo.isCaptureActivate);
174	    if (rc < 0) {
175	        return rc;
176	    }
177	    if (streamSynchronize) {
178	        rc = DynamicLaunchSynchronize(launchInfo.schedStream, launchInfo.ctrlStream, aicoreStream);
179	        ASSERT(DevCommonErr::PARAM_CHECK_FAILED, DevMemoryPool::Instance().CheckAllSentinels());
180	    }
181	    MACHINE_LOGI("finish Kernel Launch.");
182	
183	    HOST_PERF_TRACE(TracePhase::RunDevRunProfile);
