138	    static uint32_t GetAiCpuNum(uint32_t aiCpuNum, uint32_t scheCpuNum, ArchInfo archInfo,
139	                                [[maybe_unused]] bool isSameCluster)
140	    {
141	        if (scheCpuNum == 1) {
142	            return scheCpuNum;
143	        }
144	
145	        if (archInfo == ArchInfo::DAV_3510) {
146	            uint32_t oneDieMinCpuNum = aiCpuNum >> 1;
147	            uint32_t oneDieMaxCpuNum = oneDieMinCpuNum + (aiCpuNum - (oneDieMinCpuNum << 1));
148	            uint32_t oneDieMinScheCpuNum = scheCpuNum >> 1;
149	            uint32_t launchCpuNum = oneDieMaxCpuNum + oneDieMinScheCpuNum;
150	            return launchCpuNum < aiCpuNum ? launchCpuNum : scheCpuNum;
151	        } else {
152	            if (!isSameCluster) {
153	                MACHINE_LOGD("Set aicpu to not enforce the same cluster.");
154	                return scheCpuNum;
155	            }
156	            // sche = 2, need launch 3 aicpu ensure cluster; sche = 3, need launch 5 aicpu
157	            uint32_t launchCpuNum = 2 * scheCpuNum - 1; // 2 : ensure cluster success
158	                                                        // when launchCpuNum >= aiCpuNum, can't use same cluster
159	            return launchCpuNum < aiCpuNum ? launchCpuNum : scheCpuNum;
