179	        // Read user configuration for launch_sched_aicpu_num
180	        uint32_t launchSchedAicpuNum = devProg->devArgs.launchSchedAicpuNum;
181	        if (launchSchedAicpuNum > 0) {
182	            // user configuration provided: use user config if within valid range
183	            if (launchSchedAicpuNum > aiCpuNum - dynamic::MAX_CONTROL_FLOW_AICPU_NUM) {
184	                MACHINE_LOGW(
185	                    "User configured launch_sched_aicpu_num=%u exceeds hardware max=%u, using max value instead.",
186	                    launchSchedAicpuNum, aiCpuNum);
